export const JUMP_TO_EXECUTE_SQL_EVENT = 'nao:jump-to-execute-sql';

const HIGHLIGHT_CLASS = 'replay-nav-highlight';
const HIGHLIGHT_DURATION_MS = 2000;

export function jumpToExecuteSql(queryId: string): boolean {
	const target = document.querySelector<HTMLElement>(`[data-execute-sql-query-id="${CSS.escape(queryId)}"]`);
	if (!target) {
		return false;
	}

	expandClosedAncestorAccordions(target);
	target.dispatchEvent(new Event(JUMP_TO_EXECUTE_SQL_EVENT));

	requestAnimationFrame(() => {
		target.scrollIntoView({ behavior: 'smooth', block: 'center' });
		target.classList.add(HIGHLIGHT_CLASS);
		window.setTimeout(() => {
			target.classList.remove(HIGHLIGHT_CLASS);
		}, HIGHLIGHT_DURATION_MS);
	});

	return true;
}

function expandClosedAncestorAccordions(el: HTMLElement) {
	const triggers: HTMLElement[] = [];
	let current: HTMLElement | null = el.parentElement;

	while (current) {
		if (current.matches('[data-slot="accordion-content"][data-state="closed"]')) {
			const item = current.closest<HTMLElement>('[data-slot="accordion-item"]');
			const trigger = item?.querySelector<HTMLElement>('[data-slot="accordion-trigger"]');
			if (trigger) {
				triggers.push(trigger);
			}
		}
		current = current.parentElement;
	}

	for (const trigger of triggers.reverse()) {
		trigger.click();
	}
}

