const handleMount = useCallback((instance: editor.IStandaloneCodeEditor, monaco: Monaco) => {
	editorInstanceRef.current = instance;
	monacoRef.current = monaco;

	instance.addCommand(monaco.KeyMod.CtrlCmd | monaco.KeyCode.KeyS, () => {
		onSaveRef.current?.();
	});

	instance.onMouseDown((e) => {
		if (e.event.detail !== 2 || !e.target.position) {
			return;
		}
		const model = instance.getModel();
		if (!model) {
			return;
		}
		const queryId = getQueryIdAtPosition(model, e.target.position);
		if (queryId) {
			jumpToExecuteSql(queryId);
		}
	});
}, []);

function getQueryIdAtPosition(model: editor.ITextModel, position: { lineNumber: number; column: number }): string | null {
	const line = model.getLineContent(position.lineNumber);
	QUERY_ID_ATTR_REGEX.lastIndex = 0;

	let match: RegExpExecArray | null;
	while ((match = QUERY_ID_ATTR_REGEX.exec(line)) !== null) {
		const valueStartColumn = match.index + 'query_id="'.length + 1;
		const valueEndColumn = valueStartColumn + match[1].length;
		if (position.column >= valueStartColumn && position.column <= valueEndColumn) {
			return match[1];
		}
	}

	return null;
}

